    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_isurNm_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_boardCheck(selfVar)
        /* sdd-asis-lifecycle:end */

